      expect(h.frames()).toEqual([
        'upsert 0 user "hello"',
        'upsert 1 assistant ""',
        'delta 1 "first "',
        'error INVALID_MESSAGE',
        'delta 1 "second"',
        'commit 1',
        'stream_end',
